/* Callout properties - applied after others */
body .callout[data-callout*="text_glow"] {
    text-shadow: 0 0 9px var(--glow-color1);
}
body .callout[data-callout*="text_light_glow"] {
    text-shadow: 0 0 4px var(--glow-color2);
}
body .callout[data-callout*="callout_glow"]  {
    box-shadow: inset 0 0 15px color-mix(in srgb, var(--glow-color2), transparent 20%);
    text-shadow: 0 0 3px var(--glow-color2);
}
body .callout[data-callout*="cutout"] {
    box-shadow: inset 5px 5px 15px color-mix(in srgb, var(--shadow-color), transparent 50%);
	border: none;
}
body .callout[data-callout*="no_icon"]  {
    --callout-icon: none;
}
body .callout[data-callout*="no_title"] {
	--callout-title-size: 0px;
	padding-top: 2px;
}
body .callout[data-callout*="no_title"] .callout-title {
	visibility: hidden;
}
body .callout[data-callout*="no_border"] {
	border: none;
}
body .callout[data-callout*="solid_border"] {
	border-style: solid;
}
body .callout[data-callout*="no_bg"] {
	background: none;
}
body .callout[data-callout*="no_stamp"] {
	background-image: none;
}
body .callout[data-callout*="no_glow"] {
	box-shadow: none;
}
body .callout[data-callout*="white_text"] {
	color: white;
}
body .callout[data-callout*="nothing"] {
    --callout-icon: none;
	--callout-title-size: 0px;
	padding-top: 2px;
	box-shadow: none;
	background: none;
	border: none;
}
body .callout[data-callout*="nothing"] .callout-title {
	visibility: hidden;
}
body .callout[data-callout*="fixed_bg"] {
	background-attachment: fixed;
	background-size: 100% auto;
	background-repeat: no-repeat;
	background-position-x: 0px;
	background-position-y: 10%;
}
body .callout[data-callout*="bg_lines"] {
	background-image: var(--nbg-whim-lines);
	background-size: auto;
	background-position: initial;
	background-repeat: unset;
}
body .callout[data-callout*="bg_net"] {
	--nett: 75%;
	--netsize: 120px;
	--netsizewidth: 122px;
	--callout-net-color: color-mix(in srgb, var(--callout-color), transparent 80%);
	background: 
		repeating-linear-gradient(45deg, var(--callout-net-color), var(--callout-net-color) var(--netsize), color-mix(in srgb, var(--nbg-draw-color), transparent var(--nett)) var(--netsize), color-mix(in srgb, var(--nbg-draw-color), transparent var(--nett)) var(--netsizewidth)),
		repeating-linear-gradient(135deg, var(--callout-net-color), var(--callout-net-color) var(--netsize), color-mix(in srgb, var(--nbg-draw-color), transparent var(--nett)) var(--netsize), color-mix(in srgb, var(--nbg-draw-color), transparent var(--nett)) var(--netsizewidth))
		;
	background-position: 50% 50%;
    background-attachment: fixed;
}
