}
body .callout[data-callout*="text_cut"] {
	color: transparent;
  	background-clip: text;
    --callout-icon: none;
	--callout-title-size: 0px;
	padding-top: 2px;
	background-color: var(--callout-color);

}
body .callout[data-callout*="text_cut"] .callout-title {
	visibility: hidden;
}
body .callout[data-callout*="text_cut"]:hover {
	border: none;
}
body .callout[data-callout*="header_font"] {
	font-family: var(--hfont);
}

/* Final callout styling */
.callout {
	background-color: color-mix(in srgb, var(--callout-color), transparent 60%);
	--icon-size: var(--callout-icon-size);
	color: color-mix(in srgb, var(--callout-color), var(--callout-lum) 60%);
}
.callout-title-inner {
	font-family: var(--hfont);
	font-weight: 200;
	font-size: var(--callout-title-size);
	color: color-mix(in srgb,var(--callout-color), var(--callout-lum) 30%);
}


