/* Filters */


.nfilter-yellow {
	filter: invert(10%) sepia(75%) saturate(150%) hue-rotate(0deg) brightness(125%) contrast(125%);
}
.nfilter-green {
	filter: invert(10%) sepia(75%) saturate(100%) hue-rotate(80deg) brightness(115%) contrast(125%);
}
.nfilter-brown {
	filter: invert(10%) sepia(75%) saturate(100%) hue-rotate(-30deg) brightness(110%) contrast(125%);
}
.nfilter-blue {
	filter: invert(10%) sepia(75%) saturate(120%) hue-rotate(200deg) brightness(110%) contrast(125%);
}
.nfilter-purple {
	filter: invert(10%) sepia(75%) saturate(120%) hue-rotate(225deg) brightness(100%) contrast(125%);
}
.nfilter-mist {
	filter: invert(10%) sepia(75%) saturate(100%) hue-rotate(225deg) brightness(110%) contrast(125%);
}
.nfilter-pink {
	filter: invert(10%) sepia(75%) saturate(120%) hue-rotate(-100deg) brightness(100%) contrast(125%);
}
.nfilter-gray {
	filter: grayscale(100%);
}

.nfilter-rotatehue {
	filter: saturate(60%) hue-rotate(var(--strongest-shift-hue-deg)) brightness(120%);
}
.nfilter-shift {
	filter: hue-rotate(var(--shift-hue-deg));
}

.nfilter-highcontrast {
	filter: brightness(120%) contrast(170%);
}
.nfilter-lowcontrast {
	filter: brightness(80%) contrast(50%);
}
.nfilter-highersat {
	filter: saturate(190%);
}
.nfilter-lowersat {
	filter: saturate(70%);
}


/* Masks */

.nmask-fade1 {
	-webkit-mask-image: linear-gradient(to bottom, 
		transparent 0%,
		black 5%, 
		black 95%, 
		transparent 100%
	);
}
