		repeating-conic-gradient(
			color-mix(in srgb, black, transparent 85%),
			color-mix(in srgb, black, transparent 95%)
		),
		repeating-conic-gradient(
			black 45deg,
			transparent
		),
		repeating-conic-gradient(
			transparent,
			color-mix(in srgb, black, transparent 50%)
		),
		repeating-conic-gradient(
			black 135deg,
			transparent
		),
		repeating-conic-gradient(
			color-mix(in srgb, black, transparent 50%),
			transparent
		),
		repeating-conic-gradient(
			transparent,
			black 270deg
		)
	;
}
.nmask-fade4 {
	-webkit-mask-image: 
		radial-gradient(
			color-mix(in srgb, black, transparent 1%), 
			transparent 100%
		),
		repeating-conic-gradient(
			color-mix(in srgb, black, transparent 0%) 320deg,
			color-mix(in srgb, black, transparent 40%)
		);		
}


.nmask-scanlines {
	-webkit-mask-image: var(--nmask-whim-scanlines);
}



/* BG Animations */


.nanim-basicgradient {
    animation: gradient 60s ease infinite;
}
@keyframes gradient {
    0% {
        background-position: 0% 50%;
    }
    50% {
        background-position: 100% 50%;
    }
    100% {
        background-position: 0% 50%;
    }
}
.nanim-hypno {
    animation: hypno 240s ease infinite;
}
@keyframes hypno {
    0% {
        background-position: 0% 50%;
		background-size: 100% 100%;
    }
    25% {
		background-size: 200% 1%;
    }
    50% {
        background-position: 50% 0%;
		background-size: 1% 1%;
    }
    75% {
		background-size: 10% 200%;
    }
    100% {
        background-position: 0% 50%;
		background-size: 100% 100%;
    }
}
.nanim-playagate {
    animation: play 360s ease infinite;
}
@keyframes play {
    0% {
        background-position: 1% 100%;
		background-size: 1% 100%;
    }
    25% {
        background-position: 50% 50%;
		background-size: 50% 50%;
    }
    50% {
        background-position: 100% 1%;
		background-size: 100% 1%;
    }
    75% {
        background-position: 50% 50%;
		background-size: 50% 50%;
    }
    100% {
        background-position: 1% 100%;
		background-size: 1% 100%;
    }
}
.nanim-slow {
    animation: slow 360s ease infinite;
}
@keyframes slow {
    0% {
        background-position: 1% 100%;
		background-size: 100% 100%;
    }
    25% {
        background-position: 50% 50%;
		background-size: 100% 50%;
    }
    50% {
        background-position: 100% 1%;
		background-size: 200% 25%;
    }
    75% {
        background-position: 50% 50%;
		background-size: 100% 50%;
    }
    100% {
        background-position: 1% 100%;
		background-size: 100% 100%;
    }
}
.nanim-drift {
    animation: drift var(--nbg-anim-speed) ease infinite;
}
@keyframes drift {
	0% {
		background-position: 20% 20%;
	}
	50% {
		background-position: 200% 200%;
	}
	100% {
		background-position: 20% 20%;
	}
}
.nanim-zoom {
    animation: zoom 360s ease infinite;
}
@keyframes zoom {
	0% {
		background-size: 20% 20%;
	}
	50% {
		background-size: 200% 200%;
	}
	100% {
		background-size: 20% 20%;
	}
}
.nanim-rotisserie {
    animation: spin 360s ease infinite;
}
@keyframes spin {
	0% {
		transform: rotate(0turn);
	}
	100% {
		transform: rotate(1turn);
	}
}

